// ===== ANCA =====

S.push({id:`anca-coxartrosi`,d:`Anca`,t:`Coxartrosi: valutazione e trattamento conservativo`,nw:1,
sub:`Artrosi dell'anca primaria e secondaria`,
mat:[MAN],
key:[`Dolore all'inguine riferito alla coscia anteriore, rigidità dopo il riposo, fine corsa rigido soprattutto in rotazione interna ed estensione`,`60% delle forme è secondaria a difetti morfologici (displasia, FAI, esiti di fratture o epifisiolisi): diagnosi precoce`,`Trattamento conservativo: educazione, controllo del peso, mobilità quotidiana, rinforzo di glutei e quadricipite, propriocezione`,`Anca e complesso lombo-pelvico lavorano insieme: valutare sempre rachide lombare e sacroiliaca`],
inq:[`Patologia articolare degenerativa con eziopatogenesi meccanica e sinovite che erode l'osso subcondrale`,`Primaria (40%, lezione): predisposizione genetica, debolezza costituzionale della cartilagine`,`Secondaria (60%): difetti acetabolari (displasia) o femorali (fratture, osteocondrite, epifisiolisi, coxa vara o valga); più grave e rapida`,`Conseguenze possibili su rachide lombare, ginocchio, controllo posturale ed equilibrio`,`Fattori di coattazione: pressione atmosferica, capsula e legamenti, muscoli, orientamento di testa e cercine, gravità`],
tab:[{t:`Muscoli dell'anca (lezione)`,h:[`Gruppo`,`Muscoli`],r:[[`Flessori`,`Ileopsoas, TFL, sartorio, retto femorale`],[`Estensori`,`Grande gluteo, ischiocrurali`],[`Adduttori`,`Otturatore esterno, adduttore breve, lungo, grande, pettineo`],[`Abduttori`,`Medio e piccolo gluteo, TFL`],[`Rotatori`,`Pelvitrocanterici (piriforme, otturatori, gemelli, quadrato) + glutei: principali stabilizzatori`]],n:`Piriforme, otturatore esterno e pettineo possono cambiare azione in base all'angolo dell'anca.`}],
sez:[{h:`Valutazione (lezione)`,b:[`Anamnesi ricca: trauma diretto, congenito o anomalia meccanica correlata (ritmo lombo-pelvico, appoggio podalico)`,`Movimento attivo in piedi e in decubito (per discriminare la gravità), goniometro`,`Movimento passivo su tutti i piani: sintomo, escursione, qualità del fine corsa`,`Analisi del cammino nelle fasi di spinta e oscillazione: anomalie e compensi`,`Dermatomi L1-L2-L3 e funzione lombare e sacroiliaca`]},{h:`Tecniche manuali (lezione)`,b:[`Mobilizzazione graduale, ritmica, senza dolore inibente: adduzione, abduzione, flessione, rotazioni, trazione diretta`,`Movimenti accessori: trazione indiretta, estensione con scivolamento anteriore della testa, traslazioni antero-posteriore e postero-anteriore`,`Rilassamento miofasciale: massaggio profondo, inibizione dei trigger point, digitopressione, stretching, pompage`,`"Bombeo" dello psoas, tecnica di Cathie (pompage del legamento ileo-lombare), decoaptazione secondo l'asse del femore`,`Trigger point frequenti: sartorio, TFL, piriforme, glutei (dolore riferito non dermatomerico, Simons 1999)`]}],
red:[`Dolore notturno non meccanico, febbre, calo ponderale: escludere infezione o neoplasia.`,`Impossibilità di carico dopo caduta nell'anziano: sospetta frattura di femore.`,`Dolore inguinale da stress nello sportivo: sospetta frattura da stress del collo femorale.`],
yel:[`Kinesiofobia, sedentarietà, convinzione che "l'artrosi si consuma col movimento".`],
tst:[[`Trendelenburg`,`Appoggio monopodalico: osservare la caduta dell'emibacino controlaterale.`,`Debolezza degli abduttori.`],[`Thomas`,`Supino, flessione massima di un'anca: la coscia opposta si solleva?`,`Retrazione dei flessori d'anca.`],[`Ober`,`Sul fianco, anca estesa e abdotta poi lasciata cadere in adduzione.`,`Retrazione della bendelletta ileotibiale.`],[`FABER (Patrick)`,`Flessione, abduzione ed extrarotazione, pressione sul ginocchio.`,`Dolore inguinale (anca) o posteriore (sacroiliaca). Nel pediatrico utile anche per Perthes.`],[`Drehmann`,`Flessione passiva dell'anca: l'arto ruota esternamente in modo obbligato.`,`Affezioni dell'anca (es. epifisiolisi, FAI).`],[`Galeazzi`,`Supino, ginocchia flesse: confrontare l'altezza delle ginocchia.`,`Dismetria degli arti inferiori.`]],
ex:[[`Isometrici di glutei e quadricipite`,`i`,`5×10 s · RPE 3-5 · quotidiano`,`Contrazioni in decubito, anche sul fianco o prono.`,`Trattenere il respiro.`,`Isotonici in catena chiusa.`],[`Ponte e abduzione in decubito laterale`,`f`,`3×10-15 · RPE 5-7 · 3/sett`,`Glute bridge bilaterale, abduzione sul fianco con anca neutra.`,`Compensare con rotazione del bacino.`,`Ponte monopodalico, elastico.`],[`Sit-to-stand e step-up`,`f`,`3×10 · RPE 5-7 · 3/sett`,`Da sedia alta a più bassa, poi step.`,`Caricare solo il lato sano.`,`Carico esterno, step più alto.`],[`Mobilità attiva quotidiana (anche in acqua)`,`m`,`10-15 min · quotidiano`,`Bici, piscina, mobilità nei range liberi.`,`Restare fermi per paura del dolore.`,`Più tempo e intensità aerobica.`],[`Equilibrio in carico parziale e CCC`,`c`,`3×30 s · quotidiano`,`Spostamenti di carico, monopodalico assistito fuori dal dolore.`,`Ginocchio in valgo, bacino che cade.`,`Superfici instabili.`]],
fasi:[{n:`Controllo dei sintomi`,w:``,o:`Educazione e dolore`,k:`Igiene posturale, gestione dei sovraccarichi, controllo ponderale, mobilizzazione passiva senza forte dolore, terapia fisica antalgica come supporto`,c:`Dolore e rigidità in calo`,e:[0,3]},{n:`Mobilità e forza`,w:``,o:`Mantenere l'articolarità e rinforzare`,k:`Allungamento di flessori ed extra/intrarotatori; grande e medio gluteo, quadricipite, core e bacino`,c:`Cammino migliore, forza in progressione`,e:[0,1,2,3]},{n:`Funzione`,w:``,o:`Propriocezione e attività`,k:`Carico parziale fuori dal dolore, CCC; correggere dismetrie o problemi delle articolazioni vicine`,c:`Obiettivi del paziente`,e:[2,4]}],
ev:[[`Esercizio terapeutico ed educazione`,`Centrale`,`Raccomandazione forte nelle linee guida sull'artrosi (verificare)`],[`Terapia manuale associata all'esercizio`,`Supporto`,`Beneficio aggiuntivo variabile`],[`Terapie fisiche antalgiche (tens, interferenziali, tecar)`,`Supporto`,`Evidenza limitata, solo sintomatico`],[`Riposo prolungato`,`Evitare`,`Peggiora forza e funzione`]],
f:[[`Simons et al. 1999 – Myofascial pain and dysfunction: trigger point manual`,`Simons 1999 myofascial trigger point`],[`Linea guida JOSPT sul dolore d'anca e artrosi (autore da identificare)`,`hip osteoarthritis clinical practice guideline exercise physical therapy`]]});

S.push({id:`anca-pta`,d:`Anca`,t:`Protesi totale d'anca (PTA)`,nw:1,
sub:`Indicazioni, precauzioni e riabilitazione`,
mat:[MAN],
key:[`Indicazioni: dolore e impotenza gravi, mancata saldatura di fratture o deformità, tumori ossei, fallimento del conservativo o di un intervento`,`Accesso postero-laterale: si seziona l'otturatore interno, poi ricucito in leggera intrarotazione; la capsula viene suturata con punti intraossei`,`Primi 3 mesi: evitare flessione oltre 80-90° + rotazione, accavallare le gambe, sedie basse`,`Scale: si sale con la gamba sana, si scende con le stampelle e la gamba operata`],
inq:[`Tipi: protesi totale, artroplastica di rivestimento (conserva la testa), protesi mini-invasiva`,`Controindicazioni: infezioni attive o sepsi, osteomielite cronica, osso inadatto alla fissazione, grave paralisi degli stabilizzatori`,`Complicanze: TVP, lussazione, infezione, mobilizzazione dell'impianto, lesioni nervose`,`Percorso standard o fast track (meno cateteri e drenaggi, analgesia con infiltrazioni locali, deambulazione immediata)`,`Il trattamento pre-operatorio serve a raccogliere dati e istruire il paziente`],
tab:[{t:`Precauzioni nei primi 3 mesi (lezione, accesso postero-laterale)`,h:[`Da evitare`,`In pratica`],r:[[`Flessione oltre 80-90° + rotazione esterna`,`Meccanismo lussante`],[`Flessione + rotazione interna`,`Meccanismo lussante`],[`Rotazioni forzate`,`Girarsi a piccoli passi`],[`Sedersi in basso`,`Sedie alte o con cuscino, rialzo per il WC`],[`Piegarsi a terra`,`Pinza per raccogliere, calzascarpe lungo`],[`Accavallare le gambe`,`Cuscino tra le gambe dormendo sul fianco sano`]],n:`Le precauzioni variano con l'accesso chirurgico (es. anteriore): seguire le indicazioni dell'équipe.`}],
red:[`Polpaccio gonfio o dolente, dispnea, dolore toracico: TVP o embolia.`,`Dolore improvviso con accorciamento e rotazione dell'arto: lussazione.`,`Febbre, ferita calda o secrezione: infezione; dolore al carico di nuova insorgenza dopo mesi: mobilizzazione.`],
yel:[`Paura di lussare, dipendenza dagli ausili, scarsa aderenza al programma.`],
tst:[[`ROM nei limiti`,`Goniometria evitando i movimenti lussanti.`,`Progressione funzionale.`],[`Trendelenburg e cammino`,`Monopodalico e analisi del passo.`,`Forza degli abduttori, schema del passo.`],[`Timed Up and Go, scale`,`Test funzionali.`,`Autonomia e rischio di caduta.`]],
ex:[[`Pompa tibio-tarsica e isometrici`,`i`,`10×5 s · ogni ora`,`Flesso-estensione delle caviglie, contrazioni di quadricipite e glutei.`,`Contrazioni troppo "statiche" e lunghe.`,`Isotonici a letto.`],[`Abduzione e isotonici a letto`,`f`,`2×10 · 2-3 volte/die`,`Abduzione da supino e sul fianco, flesso-estensione nei limiti.`,`Superare 80-90° di flessione.`,`Elastico.`],[`Passaggi posturali e cammino con ausili`,`c`,`Più volte/die`,`Letto-sedia, alzarsi, cammino con deambulatore o canadesi.`,`Ruotare sul piede operato.`,`Riduzione progressiva degli ausili.`],[`Trasferimento del carico`,`c`,`3×10 · quotidiano`,`Spostamenti di carico anche con bilance, verso il monopodalico.`,`Evitare di caricare l'arto operato.`,`Pedane oscillanti a difficoltà crescente.`],[`Rinforzo di medio e grande gluteo`,`f`,`3×12 · RPE 5-7 · 3/sett`,`Ponte, abduzione in piedi, step-up.`,`Bacino che cade in appoggio.`,`Carico e monopodalico.`]],
fasi:[{n:`Post-operatorio immediato`,w:`carico parziale`,o:`Dolore, prevenzione delle complicanze, ROM, riattivazione`,k:`Crioterapia, igiene posturale (prevenire la retrazione in flessione), calza elastica, posizione declive, isometrie e isotonici di quadricipite e abduttori, passaggi posturali, schema del passo, endurance`,c:`Autonomia nei passaggi e nel cammino con ausili`,e:[0,1,2,3]},{n:`Carico totale`,w:``,o:`Stabilizzatori del bacino e cammino`,k:`Medio e grande gluteo, propriocezione, monopodalico, svezzamento dagli ausili`,c:`Cammino senza zoppia, Trendelenburg negativo`,e:[3,4]},{n:`Funzione`,w:`>3 mesi`,o:`Fine delle precauzioni, attività personali`,k:`Rinforzo e attività aerobica`,c:`Obiettivi del paziente`,e:[4]}],
ev:[[`Mobilizzazione e carico precoci con programma strutturato`,`Centrale`,`Fast track ben supportato (verificare)`],[`Crioterapia e calza elastica`,`Supporto`,`Dolore ed edema; profilassi`],[`Movimenti lussanti nei primi 3 mesi`,`Evitare`,`—`]],
f:[[`Revisione sulla riabilitazione dopo protesi totale d'anca (autore da identificare)`,`total hip arthroplasty rehabilitation exercise systematic review`]]});

S.push({id:`anca-fx-femore`,d:`Anca`,t:`Frattura del femore prossimale (riabilitazione post-chirurgica)`,nw:1,
sub:`Intervento scelto per tipo di frattura e paziente`,
mat:[MAN],
key:[`Mobilizzazione e verticalizzazione precoci, anche senza carico: importanza fisica e psicologica`,`Carico secondo indicazione ortopedica: da senza carico a parziale a completo`,`Recupero di 80-90° di flessione con l'attivo-assistito nelle prime 2-4 settimane`],
inq:[`Intervento (osteosintesi o protesi) in base al tipo di frattura e alle caratteristiche del paziente`,`Allungare i muscoli che si accorciano: flessori plantari, flessori d'anca, ischiocrurali`,`Rinforzare arti superiori, tronco, arto sano e distretti non coinvolti dell'arto operato`,`Dopo circa 15 giorni: presa visione della cicatrice, scollamento e massaggio drenante; kinesio tape drenante post-chirurgico`],
red:[`TVP, delirium, piaghe, infezione della ferita, dolore crescente con accorciamento dell'arto.`],
yel:[`Paura di cadere, depressione, isolamento, perdita di autonomia.`],
tst:[[`Timed Up and Go`,`Alzarsi, camminare 3 m, girarsi e sedersi.`,`Mobilità e rischio di caduta.`],[`Equilibrio`,`Berg Balance Scale o Tinetti.`,`Rischio di caduta.`]],
ex:[[`Mobilizzazione passiva precoce (manuale o kinetec)`,`m`,`2×10 · 2/die`,`Flesso-estensione nei limiti.`,`Forzare oltre il dolore.`,`Attivo-assistito.`],[`Rinforzo globale`,`f`,`2-3×10 · RPE 4-6`,`Arti superiori, tronco, arto sano.`,`Trascurare l'arto sano.`,`Isotonici dell'arto operato.`],[`Verticalizzazione e cammino`,`c`,`Più volte/die`,`Parallele, deambulatore o canadesi; carico secondo prescrizione.`,`Anticipare il carico non concesso.`,`Carico completo e aumento della distanza.`],[`Capacità aerobica e propriocezione`,`c`,`10-20 min · quotidiano`,`Cyclette, cammino, esercizi di equilibrio.`,`Sottovalutare la fatica.`,`Esercizi di equilibrio dinamico.`]],
fasi:[{n:`Precoce`,w:`0-2/4 sett.`,o:`Prevenire le complicanze da immobilizzazione`,k:`Mobilizzazione passiva, rinforzo dei distretti liberi, allungamenti, verticalizzazione precoce`,c:`Flessione 80-90°, passaggi posturali`,e:[0,1,2]},{n:`Cammino`,w:``,o:`Dal carico nullo al carico completo`,k:`Su indicazione ortopedica`,c:`Cammino autonomo con ausili`,e:[1,2,3]},{n:`Rinforzo`,w:``,o:`Forza, propriocezione, resistenza`,k:``,c:`Autonomia nelle ADL, riduzione del rischio di caduta`,e:[1,3]}],
ev:[[`Mobilizzazione precoce e programma di rinforzo progressivo`,`Centrale`,`Supportato (verificare linee guida)`],[`Kinesio tape drenante`,`Supporto`,`Evidenza limitata`]],
f:[[`Revisione sulla riabilitazione dopo frattura di femore (autore da identificare)`,`hip fracture rehabilitation exercise systematic review`]]});

S.push({id:`anca-fai`,d:`Anca`,t:`Conflitto femoro-acetabolare (FAIS) e artroscopia`,nw:1,
sub:`Cam, pincer e forme miste`,
mat:[MAN,`Manuale schede (ChatGPT) – schede 19-20`],
key:[`Piccole anomalie ossee di collo femorale (cam) o acetabolo (pincer), o miste, con usura rapida dell'anca`,`La diagnosi di FAIS richiede sintomi + segni + imaging coerenti: la morfologia da sola non è malattia (Warwick 2016)`,`Prima linea: educazione, forza, modifica del gesto; consulto chirurgico se sintomi e disabilità persistono`],
inq:[`Valutare ROM, FADIR nel contesto, forza, controllo di squat e cambi di direzione`,`Escludere frattura da stress, patologia addominale, infezione`,`Ridurre flessione profonda, adduzione e rotazione interna provocative; lo stretching non corregge la morfologia`,`Cam e pincer si trovano anche in anche senza dolore: in calciatori professionisti asintomatici la morfologia era associata a rotazione interna ridotta e a dolore alla provocazione, ma ogni associazione era debole e i test di screening discriminavano poco tra le morfologie (Mosler 2018). Per questo un test positivo o un'immagine da soli non fanno diagnosi`,`Dopo artroscopia (osteoplastica, sutura labrale, chiusura capsulare, microfratture): carico spesso parziale 2-4 settimane, limiti di flessione e rotazioni secondo chirurgo`],
red:[`Blocco, trauma importante, dolore notturno non meccanico, febbre.`,`Dopo artroscopia: TVP, dolore crescente, deficit nervoso persistente.`],
yel:[`Paura, perdita di fiducia nei gesti in posizione bassa.`],
tst:[[`FADIR`,`Flessione 90°, adduzione e rotazione interna.`,`Sensibile ma poco specifico: utile per escludere se negativo.`],[`FABER`,`Flessione, abduzione, rotazione esterna.`,`Dolore inguinale o rigidità.`],[`HHD multiassiale`,`Abduttori, adduttori, flessori.`,`Deficit di forza da trattare.`],[`Squat monopodalico e hop`,`Qualità e dolore.`,`Controllo e tolleranza.`]],
ex:[[`Isometrie d'anca`,`i`,`4×20 s · RPE 4-6`,`Abduzione e adduzione in posizione neutra.`,`Lavorare in flessione profonda dolorosa.`,`Isotonici.`],[`Hip thrust e split squat a profondità tollerata`,`f`,`3×8-12 → 4×6-8 · RPE 7-8 · 2-3/sett`,`Glutei e quadricipite nel ROM indolore.`,`Scendere in flessione dolorosa.`,`Più carico e ROM.`],[`Adduttori e abduttori`,`f`,`3×10-12`,`Cavo o elastico, Copenhagen corto.`,`Dolore inguinale persistente.`,`Copenhagen lungo.`],[`Salti e COD`,`p`,`3×5 · 2/sett`,`Salti sagittali e laterali, frenate.`,`Introdurli prima della forza.`,`Posizioni basse e contatto.`]],
fasi:[{n:`Irritabilità`,w:`1-3 sett.`,o:`Adattare profondità di squat, bici e seduta`,k:`Attività tollerate`,c:`Cammino e compiti di base stabili`,e:[0]},{n:`ROM e forza`,w:`6-12 sett.`,o:`Glutei, adduttori e tronco nel ROM tollerato`,k:``,c:`Squat monopodalico controllato`,e:[0,1,2]},{n:`SSC`,w:``,o:`Salti, atterraggi, frenate`,k:``,c:`Hop e COD senza dolore`,e:[1,2,3]},{n:`Campo`,w:``,o:`Corsa, COD, calci, posizioni basse`,k:`Consulto se persistono sintomi coerenti con la struttura`,c:`Allenamento completo tollerato`,e:[1,3]}],
ev:[[`Educazione, forza e modifica del gesto`,`Centrale`,`Limitata o consenso per dettagli`],[`Manualità selezionata senza forzare il conflitto`,`Supporto`,`Selettivo`],[`Chirurgia sulla sola morfologia; stretching aggressivo nel dolore inguinale`,`Evitare`,`—`]],
f:[[`Mosler et al. 2018 – morfologia ossea dell'anca, mobilità e forza in calciatori asintomatici (JOSPT)`,`Mosler 2018 bony hip morphology range of motion strength asymptomatic male soccer players`,`PMID 29548272`],[`Griffin et al. 2016 – Warwick Agreement sulla FAIS (BJSM)`,`Griffin 2016 Warwick agreement femoroacetabular impingement syndrome`,`PMID 27629403`],[`Takla et al. 2021 – consensus ISHA sulla riabilitazione`,`Takla 2021 ISHA consensus rehabilitation femoroacetabular impingement`,`PMID 34377507`]]});

S.push({id:`anca-gtps`,d:`Anca`,t:`Dolore laterale d'anca (tendinopatia glutea e borsite trocanterica)`,nw:1,
sub:`Greater trochanteric pain syndrome`,
mat:[MAN,`Manuale schede (ChatGPT) – scheda 21`],
key:[`Dolore laterale provocato dal carico; la compressione in adduzione peggiora i sintomi`,`Educazione + carico progressivo degli abduttori (RCT LEAP, Mellor 2018)`,`Evitare gambe accavallate, decubito sul lato dolente, stretching in adduzione`],
inq:[`Tendinopatia di medio e piccolo gluteo, spesso con borsite trocanterica`,`Distinguere da rachide lombare, artrosi, rotture tendinee`,`Dati di Mellor soprattutto su adulti di mezza età: trasferimento prudente all'atleta`],
red:[`Dolore notturno non meccanico, febbre, impossibilità al carico.`],
yel:[`Sonno disturbato, paura del cammino.`],
tst:[[`Palpazione del gran trocantere`,`Dolorabilità laterale.`,`Supporta la diagnosi.`],[`Appoggio monopodalico 30 s`,`In piedi su un arto.`,`Riproduzione del dolore laterale.`],[`FADER / FABER-R`,`Adduzione o abduzione resistita in posizioni compressive.`,`Provocazione del tendine gluteo.`]],
ex:[[`Abduzione isometrica in posizione neutra`,`i`,`4×30 s · RPE 4-6`,`Supino o in piedi, spinta laterale contro una cintura.`,`Lavorare in adduzione.`,`Isotonici in piedi.`],[`Abduzione in piedi, ponte, step-up`,`f`,`3×10-12 → 4×6-8 · RPE 7-8 · 3/sett`,`Bacino stabile.`,`Side-lying sul lato dolente.`,`Squat e split squat.`],[`Saltelli laterali`,`p`,`3×10`,`Dopo controllo pelvico.`,`Flare il giorno dopo.`,`COD.`]],
fasi:[{n:`Irritabilità`,w:`1-3 sett.`,o:`Educazione e riduzione della compressione`,k:`Cammino dosato`,c:`Sonno e attività migliorano`,e:[0]},{n:`Forza`,w:`6-12 sett. o più`,o:`Abduttori e catena`,k:``,c:`Monopodalico indolore`,e:[0,1]},{n:`SSC e campo`,w:``,o:`Corsa, COD, contatto`,k:``,c:`Nessun dolore limitante in corsa`,e:[1,2]}],
ev:[[`Educazione sulla compressione e carico progressivo`,`Centrale`,`Moderata (Mellor 2018)`],[`Infiltrazione dopo valutazione medica`,`Supporto`,`Beneficio breve`],[`Stretching compressivo e solo trattamento passivo`,`Evitare`,`—`]],
f:[[`Mellor et al. 2018 – RCT LEAP: educazione ed esercizio nella tendinopatia glutea (BMJ)`,`Mellor 2018 education plus exercise gluteal tendinopathy LEAP randomised`,`PMID 29720374`]]});

S.push({id:`anca-groin`,d:`Anca`,t:`Dolore inguinale nell'atleta (classificazione di Doha)`,nw:1,
sub:`Adduttori, ileopsoas, inguine e pube`,
mat:[`Manuale schede (ChatGPT) – schede 22-25`],
key:[`Non chiamare tutto "pubalgia": classificare per entità clinica (Doha 2015)`,`Le entità possono coesistere; la clinica guida, non la RM da sola`,`Il rinforzo degli adduttori (Copenhagen) riduce il groin pain nel calcio (Harøy 2019): trasferimento ragionato al rugby`,`Nelle lesioni acute la palpazione negativa dell'adduttore lungo è il dato che meglio esclude una lesione alla RM (valore predittivo negativo 91-96%, Serner 2016); i test dei flessori d'anca predicono male (Serner 2016)`],
tab:[{t:`Entità cliniche (Doha 2015)`,h:[`Entità`,`Clinica`,`Approccio`],r:[[`Adduttori`,`Dolorabilità adduttoria + dolore con adduzione resistita`,`Rinforzo adduttori progressivo (Hölmich 1999)`],[`Ileopsoas`,`Dolorabilità dell'ileopsoas + dolore con flessione resistita e/o stretching`,`Carico dei flessori, gestione dei calci`],[`Inguinale`,`Dolore nel canale inguinale, ernia non palpabile`,`Valutazione, rinforzo, eventuale chirurgo`],[`Pubico`,`Dolorabilità della sinfisi`,`Carichi simmetrici poi asimmetrici, percorso lungo`],[`Correlato all'anca`,`Dolore inguinale con limitazione o dolore ai movimenti dell'anca, spesso rotazione ridotta`,`Valutare mobilità e forza d'anca; la rotazione totale delle due anche sotto 85° in pre-stagione è un fattore di rischio (Tak 2017); se sospetto, invio`],[`Altre cause`,`Anca (FAI), frattura da stress, cause urologiche o addominali`,`Invio se sospetto`]]}],
inq:[`Valutare HAGOS, forza (squeeze a più angoli), calci e carico settimanale`,`Ridurre calci e tagli provocativi senza riposo totale`,`Meccanismo dell'adduttore lungo: in 17 calciatori professionisti l'infortunio acuto è avvenuto più spesso senza contatto (71%), dopo una reazione rapida a un cambio di gioco (53%); i gesti erano cambio di direzione (35%), calcio (29%), reaching (24%) e salto (12%). Il meccanismo di fondo è una contrazione rapida durante un allungamento rapido (Serner 2018, video analisi). Non esistono analisi simili nel rugby tra le fonti verificate: il parallelo con tagli, accelerazioni e calci è un ragionamento clinico, non un dato`,`Imaging: non è il criterio diagnostico. È un commento clinico a più autori (Thorborg 2018) a ricordare che la classificazione resta clinica; un lavoro su calciatori asintomatici mostra anche che le alterazioni ossee dell'anca sono frequenti senza dolore (Mosler 2018, vedi la scheda sul FAIS)`,`Misura di esito: tra i questionari per anca e inguine la revisione sistematica raccomanda HAGOS, e HAGOS è l'unico pensato anche per chi ha dolore inguinale (Thorborg 2015). Nella versione olandese affidabilità e coerenza interna sono buone, con effetto pavimento (21%) nella sottoscala dell'attività fisica (Tak 2018)`],
red:[`Dolore testicolare, massa, sintomi addominali, febbre, dolore osseo crescente (frattura da stress del pube o del collo femorale).`],
yel:[`Lunga durata, sonno, bassa fiducia nel taglio.`],
tst:[[`Palpazione dell'adduttore lungo`,`Tendine prossimale e origine sul pube, confronto con il lato sano.`,`Se non c'è dolore, una lesione adduttoria acuta è molto improbabile (valore predittivo negativo 91-96% alla RM, Serner 2016, su 81 atleti con lesione acuta).`],[`Squeeze test`,`Adduzione a 0°, 45° e 90° di flessione d'anca contro i pugni del terapista o un dinamometro. Nello studio di Serner 2016 i setup positivi erano lo squeeze con anca neutra e leva lunga, l'adduzione resistita in range esterno e lo stretching passivo degli adduttori.`,`Dolore e forza degli adduttori. Quando uno di questi tre test è positivo, la probabilità di una lesione adduttoria alla RM è dell'80-81% (Serner 2016, lesioni acute).`],[`Stretching passivo degli adduttori`,`Abduzione passiva dell'anca a ginocchio esteso, confronto con il lato sano.`,`Dolore riconoscibile nella sede adduttoria (Serner 2016).`],[`Flessione resistita e Thomas`,`Ileopsoas.`,`Dolore riconoscibile. Nelle lesioni acute i test dei flessori d'anca hanno predetto male la lesione alla RM (valore predittivo positivo 34-63%): da interpretare con prudenza (Serner 2016).`],[`Palpazione della sinfisi`,`Pressione diretta.`,`Entità pubica.`],[`HAGOS`,`Questionario compilato dall'atleta all'inizio e a intervalli regolari (frequenza: proposta operativa). Il modulo è collegato qui sotto.`,`Funzione riferita; utile per seguire il cambiamento nel tempo. Soglie di rientro con HAGOS non sono state verificate. Nello studio di validazione originale (101 pazienti con dolore a lunga durata) il cambiamento minimo rilevabile era di 17,7-33,8 punti sul singolo atleta e di 2,7-5,2 sul gruppo, a seconda della sottoscala (Thorborg 2011): una variazione di pochi punti nel singolo non basta a dire che è migliorato.`]],
ex:[[`Squeeze isometrico`,`i`,`4-5×10-30 s · RPE 3-6`,`Pallone o pugni tra le ginocchia.`,`Dolore che resta dopo.`,`Più angoli e forza.`],[`Adduzione al cavo`,`f`,`3×10-12 → 4×6-8 · RPE 7-8`,`In piedi, controllo del bacino.`,`Ruotare il tronco.`,`Copenhagen.`],[`Copenhagen corto → lungo`,`f`,`2×6 → 3×6-8 · 2-3/sett`,`Plank laterale con l'arto superiore su panca (ginocchio poi piede).`,`Bacino che cede.`,`Più leva e ripetizioni.`],[`Antirotazione e flessori d'anca`,`c`,`3×10`,`Pallof press, march con elastico.`,`Compenso lombare.`,`Più carico.`]],
fasi:[{n:`Irritabilità`,w:`1-3 sett.`,o:`Gestione del volume, condizionamento non provocativo`,k:``,c:`Squeeze e cammino stabili`,e:[0]},{n:`Forza`,w:`8-12 sett. o oltre`,o:`Adduttori, abduttori, tronco`,k:``,c:`Squeeze ≥90% e indolore`,e:[0,1,2,3]},{n:`SSC e COD`,w:`2-3 sett. (proposta)`,o:`Balzi laterali, decelerazioni, tagli`,k:``,c:`COD senza dolore`,e:[2,3]},{n:`Campo`,w:`2-4 sett. (proposta)`,o:`Sprint, calci, tagli reattivi, contatto`,k:`Mantenere Copenhagen 1-2/sett.`,c:`Allenamento pieno senza flare`,e:[2,3]}],
ev:[[`Allenamento attivo e gestione delle esposizioni`,`Centrale`,`Moderata (Hölmich 1999)`],[`Programma Copenhagen in prevenzione`,`Centrale`,`RCT nel calcio maschile (Harøy 2019); in 8 settimane la forza eccentrica degli adduttori è aumentata del 35,7% in 24 giovani calciatori (Ishøi 2016, studio piccolo che misura la forza, non gli infortuni)`],[`Esame clinico standardizzato: palpazione e test specifici degli adduttori`,`Centrale`,`Studio su 81 atleti con lesione acuta (Serner 2016); non vale per il dolore di lunga durata`],[`Tempi realistici di recupero`,`Da tenere presenti`,`Il programma di Hölmich dura 8-12 settimane per il dolore di lunga durata (Hölmich 1999). In due studi piccoli e senza gruppo di controllo che lo hanno riprodotto per 10 settimane il rientro è avvenuto in media a 14,2 settimane (intervallo 10-20, Yousefzadeh 2018, 17 atleti) e a 12,1 settimane (Yousefzadeh 2018, protocollo modificato, 15 atleti). Non ho trovato dati sui tempi per un problema recente di poche settimane: le durate delle fasi 3 e 4 sono proposte operative`],[`Effetto a lungo termine dell'allenamento attivo`,`Centrale`,`Follow-up a 8-12 anni di 47 dei 59 atleti dell'RCT originale: l'effetto del programma è rimasto significativo (Hölmich 2011)`],[`Copenhagen in riabilitazione`,`Supporto`,`RCT piccolo su 30 calciatori con dolore da adduttori, 2 sedute a settimana per 8 settimane: più forza eccentrica (+0,49 Nm/kg), meno dolore e HAGOS migliore nel gruppo con Copenhagen (Alsirhani 2024). Studio piccolo, solo calcio maschile`],[`Soli massaggi o stretching; diagnosi da RM senza clinica`,`Evitare`,`L'imaging non basta per classificare (Thorborg 2018, commento clinico); il resto è pratica clinica`]],
rts:{intro:`Non esistono criteri di rientro validati per il dolore inguinale nell'atleta: i criteri qui sotto sono proposte operative costruite sui gesti del rugby (cambi di direzione, sprint, calcio, contatto), con il dinamometro manuale in kg.`,c:[[`Test provocativi`,`Palpazione dell'adduttore lungo, squeeze test a 0°, 45° e 90°, stretching passivo`,`Negativi, dolore 0-1/10 (proposta operativa)`,`Sono i test che riproducono il dolore dell'atleta e che l'esame clinico considera più utili (Serner 2016).`],[`Forza degli adduttori`,`Dinamometro manuale in kg, squeeze a 45° con ginocchia piegate, confronto tra lati`,`LSI ≥90% (proposta operativa)`,`Una forza adduttoria bassa è un fattore su cui lavora il programma Copenhagen; il confronto tra lati dà un riferimento semplice.`],[`Cambi di direzione`,`Tagli a 45° e 90°, frenate e cambi reattivi, prima pianificati poi reattivi`,`Senza dolore e senza flare nelle 24 ore (proposta operativa)`,`Il cambio di direzione è il gesto più frequente nelle lesioni acute dell'adduttore lungo (Serner 2018, calcio).`],[`Calcio e sprint`,`Calci di precisione poi massimali, sprint lineari fino alla velocità massima`,`Tollerati senza dolore (proposta operativa)`,`Il calcio e il reaching sono tra i gesti infortunanti descritti (Serner 2018); la scheda sull'ileopsoas tratta i flessori d'anca.`],[`Contatto e placcaggio`,`Placcaggi controllati poi in velocità, mischia e ruck con apertura delle gambe`,`Tollerati nell'allenamento pieno (proposta operativa)`,`Il rugby chiede posizioni di abduzione e spinta che i test in palestra non riproducono.`],[`Misura riferita`,`HAGOS compilato dall'atleta`,`Nessuna soglia validata: usarlo per vedere il trend e per il confronto con il valore iniziale (proposta operativa)`,`Questionario raccomandato per questa popolazione (Thorborg 2015), ma i cut-off per il rientro non sono stati verificati.`]],pre:[],nota:`Se un criterio fallisce, si torna alla fase precedente per una o due settimane e si ripete la misura.`},
sez:[{h:`Prevenzione`,b:[`Il programma Copenhagen, aggiunto all'allenamento, riduce i problemi inguinali nel calcio maschile (Harøy 2019, RCT a cluster); nel rugby non ci sono studi verificati qui: trasferimento ragionato`,`Dose, frequenza e progressione (per esempio 2-3 volte a settimana in preparazione e una a settimana in stagione, partire da un livello facile e regredire se il dolore supera 3/10) sono proposte operative: nelle fonti verificate non sono riportate`,`Dopo un episodio, mantenere il lavoro sugli adduttori e rivalutare la forza in stagione (proposta operativa)`,`Aumentare in modo graduale calci, sprint e tagli, soprattutto dopo uno stop (proposta operativa)`]}],
f:[[`Weir et al. 2015 – Doha agreement sul groin pain (BJSM)`,`Weir 2015 Doha agreement groin pain athletes`,`PMID 26031643`],[`Hölmich et al. 1999 – RCT: allenamento attivo nel dolore inguinale da adduttori (Lancet)`,`Holmich 1999 active training adductor-related groin pain randomised`,`PMID 9989713`],[`Harøy et al. 2019 – RCT a cluster: programma adduttori e prevenzione (BJSM)`,`Haroy 2019 adductor strengthening programme groin problems randomised`,`PMID 29891614`],[`Thorborg et al. 2018 – esame clinico, imaging e test nell'atleta con dolore inguinale, commento clinico (JOSPT)`,`Thorborg 2018 clinical examination diagnostic imaging testing athletes groin pain`,`PMID 29510653`],[`Serner et al. 2016 – l'esame clinico predice la presenza e la sede dei reperti alla RM nelle lesioni inguinali acute (BJSM)`,`Serner 2016 standardised clinical examination acute groin injuries MRI findings`,`PMID 27531521`],[`Serner et al. 2018 – meccanismi delle lesioni acute dell'adduttore lungo nel calcio, analisi video (BJSM)`,`Serner 2018 mechanisms acute adductor longus injuries football video analysis`,`PMID 30006458`],[`Ishøi et al. 2016 – RCT: esercizio Copenhagen e aumento della forza eccentrica degli adduttori nel calcio (SJMSS)`,`Ishoi 2016 Copenhagen adduction exercise eccentric strength football randomized`,`PMID 26589483`],[`Thorborg et al. 2015 – questionari per anca e inguine in giovani adulti, revisione sistematica (BJSM)`,`Thorborg 2015 patient-reported outcome questionnaires hip groin disability systematic review`,`PMID 25586913`],[`Thorborg et al. 2011 – HAGOS: sviluppo e validazione (BJSM)`,`Thorborg 2011 Copenhagen Hip and Groin Outcome Score HAGOS development validation COSMIN`,`PMID 21478502`],[`Hölmich et al. 2011 – effetto dell'allenamento fisico a 8-12 anni, follow-up dell'RCT (AJSM)`,`Holmich 2011 continued significant effect physical training overuse injury 8 to 12 year outcome`,`PMID 21813441`],[`Alsirhani et al. 2024 – RCT: esercizio Copenhagen in calciatori con dolore da adduttori (Phys Sportsmed)`,`Alsirhani 2024 Copenhagen adduction exercise eccentric strength soccer players groin injury randomized`,`PMID 38376593`],[`Yousefzadeh et al. 2018 – protocollo di Hölmich, valutazione oggettiva (BMJ Open Sport Exerc Med)`,`Yousefzadeh 2018 Holmich protocol exercise therapy long-standing adductor-related groin pain objective evaluation`,`PMID 30018787`],[`Yousefzadeh et al. 2018 – protocollo di Hölmich modificato (Rehabil Res Pract)`,`Yousefzadeh 2018 therapeutic exercise long-standing adductor-related groin pain modified Holmich protocol`,`PMID 29721339`],[`Tak et al. 2017 – la minor mobilità d'anca è un fattore di rischio per il dolore inguinale? Revisione sistematica (BJSM)`,`Tak 2017 lower hip range of motion risk factor groin pain athletes systematic review`,`PMID 28432076`],[`Tak et al. 2015 – mobilità d'anca in calciatori professionisti con sintomi o infortuni inguinali, indipendente dalla cam (AJSM)`,`Tak 2015 hip range of motion professional soccer players hip groin symptoms cam deformities`,`PMID 26673034`],[`Tak et al. 2018 – HAGOS olandese, adattamento e validazione (JOSPT)`,`Tak 2018 Dutch Hip and Groin Outcome Score cross-cultural adaptation validation`,`PMID 29607768`],[`Mosler et al. 2018 – morfologia ossea dell'anca, mobilità e forza in calciatori asintomatici (JOSPT)`,`Mosler 2018 bony hip morphology range of motion strength asymptomatic male soccer players`,`PMID 29548272`]]});

S.push({id:`avulsioni-apofisarie-bacino`,d:`Anca`,t:`Avulsioni apofisarie del bacino nell'adolescente`,nw:1,
sub:`SIAS, SIAI, tuberosità ischiatica e piccolo trocantere: sprint e calcio, conservativo quasi sempre, rientro per criteri`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`Lesione tipica dell'adolescente sportivo (età media tra 14 e 15 anni nelle casistiche): una contrazione violenta stacca l'apofisi, il punto più debole finché la cartilagine di accrescimento è aperta`,`Sedi più frequenti: spina iliaca antero-inferiore (SIAI, retto femorale), spina iliaca antero-superiore (SIAS, sartorio), tuberosità ischiatica (ischiocrurali); meccanismi principali corsa o sprint e calcio (Schuett 2015, Ferraro 2023)`,`Il conservativo è la regola: 86,6% dei casi nella metanalisi di Molina 2026, successo nel 97% della casistica di Schuett 2015; il ritorno allo sport è raggiunto quasi sempre`,`La dislocazione conta, ma non esiste una soglia validata per operare (Molina 2026): Eberbach 2017 suggerisce di considerare la chirurgia oltre 15 mm con alte richieste funzionali; oltre 20 mm il rischio di pseudoartrosi è 26 volte maggiore (Schuett 2015)`,`Con il conservativo e la fisioterapia, a 3 mesi o più la forza dell'arto colpito è uguale a quella del lato sano (Ratcliff 2025, 28 ragazzi); tuberosità ischiatica e SIAI sono le sedi più esposte a pseudoartrosi e dolore persistente`,`Nel rugby giovanile gli stessi gesti (sprint, calcio, partenze esplosive) caricano queste apofisi, ma non sono stati trovati studi specifici sul rugby`],
inq:[`Meccanismo: contrazione improvvisa e violenta del muscolo che si inserisce sull'apofisi, durante sprint, calcio, salto o cambio di direzione (Rossi 2001). Spesso il ragazzo riferisce uno schiocco e un dolore acuto e localizzato (pratica clinica)`,`Epidemiologia: nelle casistiche più ampie prevalgono i maschi (76-79%) e l'età media è 14,4-14,6 anni (Schuett 2015, Ferraro 2023, Molina 2026). Nel centro di Ferraro 2023 (719 fratture) i casi trattati ogni anno sono passati da 17 nel 2005 a 75 nel 2019`,`La distribuzione per sede cambia tra le casistiche: la SIAI è la prima in Schuett 2015 (49%) e Ferraro 2023 (33,4%), la SIAS in Molina 2026 (33,1%), la tuberosità ischiatica nella casistica radiografica di Rossi 2001 (109 casi su 203, soprattutto calcio e ginnastica)`,`Ogni sede ha un profilo proprio di età, sesso, meccanismo e sport (Ferraro 2023): per esempio metà delle avulsioni della SIAI nasce da un calcio (Schuett 2015). Alcuni ragazzi riferiscono dolore nella sede già prima dell'evento acuto (sintomi prodromici, Ferraro 2023)`,`Diagnosi: la radiografia standard del bacino è determinante (Rossi 2001); ecografia o RM servono quando la RX è dubbia o il frammento è poco visibile (pratica clinica)`,`Prognosi: dolore oltre 3 mesi nel 14% dei casi, 4,47 volte più probabile nelle avulsioni della SIAI; 5 pseudoartrosi su 228 avulsioni, 4 della tuberosità ischiatica (Schuett 2015). Le avulsioni ischiatiche operate hanno i tempi di recupero più lunghi, circa 6 mesi (Molina 2026)`,`L'avulsione ischiatica dell'adolescente è il corrispettivo giovanile dell'avulsione prossimale degli hamstring dell'adulto (vedi la scheda dedicata nella sezione Muscoli); il distacco del piccolo trocantere riguarda l'ileopsoas (vedi anche la scheda sul dolore inguinale correlato all'ileopsoas)`],
tab:[{t:`Sedi, muscolo e gesto tipico`,z:`I`,h:[`Sede`,`Muscolo che strappa`,`Gesto tipico`],r:[[`SIAS`,`Sartorio (e tensore della fascia lata)`,`Sprint, partenza esplosiva`],[`SIAI`,`Retto femorale (capo diretto)`,`Calcio (metà dei casi in Schuett 2015), sprint`],[`Tuberosità ischiatica`,`Ischiocrurali`,`Flessione d'anca forzata a ginocchio esteso: sprint, spaccata, calcio`],[`Piccolo trocantere`,`Ileopsoas`,`Flessione d'anca contro resistenza, sprint (30 casi, età media 14,2 anni in Volpi 2021)`],[`Cresta iliaca`,`Muscoli addominali`,`Rotazione brusca del tronco, cambio di direzione`],[`Angolo superiore della sinfisi pubica`,`Adduttori`,`Sede rara (7 casi su 203 in Rossi 2001)`],[`Nota`,`Corrispondenze muscolo-sede e gesti dai testi di anatomia e traumatologia`,`Il dato sul calcio nella SIAI viene da Schuett 2015`]]},{t:`Conservativo o chirurgia: cosa dicono gli studi`,z:`T`,h:[`Dato (fonte)`,`Valore`],r:[[`Fratture trattate in modo conservativo (Molina 2026, 24 studi, 852 fratture)`,`86,6%`],[`Conservativo riuscito (Schuett 2015, 228 avulsioni)`,`97%; chirurgia indicata nel 3%`],[`Ritorno allo sport, chirurgia vs conservativo (Eberbach 2017, 14 studi, 596 pazienti)`,`92% vs 80%, differenza significativa`],[`Successo complessivo, chirurgia vs conservativo (Eberbach 2017)`,`88% vs 79%, differenza non significativa`],[`Dolore persistente nelle avulsioni ischiatiche (Molina 2026)`,`27,3% operate, 10,9% conservative`],[`Dolore persistente nella SIAI trattata in modo conservativo (Molina 2026)`,`13,8%`],[`SIAS dislocate oltre 15 mm (Molina 2026)`,`Esiti eccellenti con entrambi; rientro più rapido solo con la chirurgia`],[`Tuberosità ischiatica dislocata oltre 15 mm (Molina 2026)`,`Buona funzione con entrambi; qualche pseudoartrosi nei conservativi, con limitazione minima`],[`Dislocazione iniziale oltre 20 mm (Schuett 2015)`,`Rischio di pseudoartrosi 26 volte maggiore`],[`Limite`,`Studi retrospettivi di qualità bassa (punteggio di Coleman medio 41,2 in Eberbach 2017), nessun RCT, nessuna soglia di dislocazione validata`]]}],
red:[`Adolescente con zoppia o impossibilità a caricare e dolore all'anca o al ginocchio senza un trauma chiaro: escludere epifisiolisi femorale e frattura del collo del femore (pratica clinica).`,`Dolore notturno o a riposo, febbre, malessere, gonfiore che cresce: escludere infezione (osteomielite, artrite settica) o tumore osseo (pratica clinica).`,`Avulsione del piccolo trocantere in un adulto, cioè a cartilagini di accrescimento chiuse: sospettare una lesione patologica, per esempio una metastasi, e inviare al medico. L'indicazione viene da case report non inclusi nelle fonti della scheda: è giudizio clinico.`,`Formicolii o debolezza della gamba dopo un'avulsione ischiatica molto dislocata: possibile coinvolgimento del nervo sciatico, consulto ortopedico (pratica clinica).`,`Frammento molto dislocato (oltre 15-20 mm), soprattutto alla tuberosità ischiatica: consulto ortopedico per discutere la chirurgia (Eberbach 2017, Schuett 2015).`],
yel:[`Pressione di allenatori o genitori per rientrare in fretta, magari con più squadre o più sport nella stessa settimana.`,`Paura di sprintare o di calciare di nuovo, con il gesto modificato per proteggersi.`,`Dolore sottovalutato come un semplice "stiramento", continuando a giocare.`],
tst:[[`Anamnesi del gesto`,`Età, sport, gesto preciso (sprint, calcio, spaccata), schiocco, dolore improvviso e localizzato, eventuale dolore nei giorni precedenti.`,`Adolescente con dolore acuto durante uno sprint o un calcio: sospettare l'avulsione prima della lesione muscolare (pratica clinica).`],[`Palpazione delle apofisi`,`SIAS, SIAI (sotto e medialmente alla SIAS), tuberosità ischiatica da prono o su un fianco, piccolo trocantere, cresta iliaca; confronto con il lato sano.`,`Un dolore puntiforme sull'osso, e non sul ventre muscolare, orienta verso l'avulsione.`],[`Contrazione resistita e allungamento`,`Flessione d'anca a ginocchio esteso e flesso, estensione del ginocchio, flessione del ginocchio da prono; allungamento del muscolo sospetto, senza forzare.`,`Dolore sulla sede ossea con il muscolo corrispondente. Non serve cercare il dolore massimo: la conferma è radiografica.`],[`RX del bacino`,`Su indicazione medica; proiezione antero-posteriore con confronto tra i due lati.`,`Determinante per la diagnosi (Rossi 2001): sede, dimensione e dislocazione del frammento. Guardare tutto il bacino: le avulsioni multiple non sono rare (6% in Schuett 2015).`],[`Ecografia o RM`,`Su indicazione medica.`,`Utili se la RX è negativa o dubbia, o per definire meglio il frammento (pratica clinica).`],[`Forza con dinamometro manuale`,`Flessione, estensione e abduzione d'anca, estensione e flessione del ginocchio, in kg; confronto tra lati con l'LSI.`,`Monitoraggio e criterio di rientro. Ratcliff 2025 ha usato misure di forza di anca e ginocchio espresse come LSI.`]],
ex:[[`Carico protetto e mobilità senza allungare`,`m`,`ROM attivo 2×10 · quotidiano; stampelle finché il passo non è libero dal dolore (proposta operativa)`,`Camminare con l'appoggio che il dolore concede; muovere l'anca nel range indolore senza portare in allungamento il muscolo che ha strappato.`,`Stretching del muscolo coinvolto nelle prime settimane.`,`Cammino libero, poi mobilità completa.`],[`Isometrici del muscolo coinvolto`,`i`,`5×30-45 s al 30-50% · RPE 3-5 · quotidiano (proposta operativa)`,`In posizione accorciata o neutra: spinta del ginocchio verso l'alto da seduto (SIAI, SIAS, piccolo trocantere), spinta del tallone contro il lettino da supino a ginocchio flesso (tuberosità ischiatica).`,`Dolore oltre 3/10 sulla sede o che resta il giorno dopo.`,`Intensità crescente, poi angoli più vicini all'allungamento.`],[`Condizionamento senza carico sulla sede`,`f`,`2-4 sedute/sett. (proposta operativa)`,`Forza della parte alta, del tronco e dell'arto sano; bici a bassa resistenza o nuoto con le gambe ferme appena tollerati.`,`Pedalare in piedi o con resistenze alte se tira sulla sede.`,`Bici più intensa, poi corsa leggera.`],[`Forza di base di anca e ginocchio`,`f`,`3×10-12 → 4×6-8 · RPE 6-8 · 2-3/sett. (proposta operativa)`,`Ponte, squat, leg press, step-up, abduzione su un fianco, leg extension leggera.`,`Caricare molto prima che la contrazione resistita sia indolore.`,`Esercizi su una gamba, carichi crescenti.`],[`Forza in allungamento del muscolo coinvolto`,`f`,`3×5-8 · RPE 6-8 · 2/sett. (proposta operativa)`,`Ischiocrurali: stacco rumeno, poi Nordic. Retto femorale: affondo con il ginocchio dietro, poi reverse Nordic. Ileopsoas e sartorio: flessione d'anca al cavo partendo dall'anca estesa.`,`Introdurli prima che la forza di base sia simmetrica.`,`Range più ampio, velocità più alta.`],[`Controllo lombo-pelvico`,`c`,`3×8-10 o 3×20-30 s (proposta operativa)`,`Dead bug, ponte su una gamba, plank laterale, Pallof press.`,`Bacino che ruota o schiena che si inarca.`,`Carico esterno, esercizi in piedi e in corsa.`],[`Corsa, sprint e calcio progressivi`,`p`,`2-3 sedute/sett., volume e velocità crescenti (proposta operativa)`,`Andature, corsa al 60-70%, allunghi, sprint all'80-90% e poi massimali; calci corti, poi lunghi, poi in gioco.`,`Iniziare dallo sprint massimale o dal calcio lungo, cioè proprio dai gesti del meccanismo.`,`Sprint con cambi di direzione, calci sotto fatica, allenamento di squadra.`]],
fasi:[{n:`Protezione`,w:`circa 0-2/3 sett. (indicativo)`,o:`Calmare il dolore, proteggere il frammento, mantenere la condizione fisica`,k:`Nella serie di Volpi 2021 (piccolo trocantere) stop dallo sport in tutti i casi e carico protetto, con una durata media del trattamento di 30,7 giorni`,c:`Cammino senza dolore, dolore alla palpazione in calo`,e:[0,1,2]},{n:`Forza di base`,w:`circa 3-6 sett. (indicativo)`,o:`Contrazione resistita indolore, forza di anca e ginocchio`,k:`Aumentare il carico solo se il dolore resta basso anche il giorno dopo (proposta operativa)`,c:`Contrazione resistita senza dolore, mobilità completa`,e:[1,2,3,5]},{n:`Forza in allungamento e corsa`,w:`circa 6-10 sett. (indicativo)`,o:`Forza simmetrica anche in allungamento, corsa lineare`,k:`Corsa lineare submassimale, niente sprint massimali né calci lunghi`,c:`LSI ≥90% al dinamometro, corsa all'80% senza dolore (proposta operativa)`,e:[3,4,5,6]},{n:`Sprint, calcio e rugby`,w:`spesso dopo 8-12 sett. (rientro medio di 11 settimane nel piccolo trocantere, Volpi 2021); circa 6 mesi nelle ischiatiche operate (Molina 2026)`,o:`Sprint massimale, calcio, contatto`,k:`Reintrodurre per ultimi i gesti del meccanismo`,c:`Criteri del capitolo del rientro`,e:[4,5,6]}],
ev:[[`Trattamento conservativo con stop sportivo, carico protetto e fisioterapia`,`Centrale`,`Metanalisi di studi osservazionali (Molina 2026) e grandi casistiche retrospettive (Schuett 2015): successo nella grande maggioranza dei casi. Nessun RCT`],[`Rinforzo progressivo dopo la fase acuta`,`Supporto`,`Coorte prospettica di 28 ragazzi (Ratcliff 2025): nessun deficit di forza a 3 mesi o più. Nessun gruppo di controllo; il contenuto del programma non è descritto nell'abstract`],[`Chirurgia nelle avulsioni molto dislocate in atleti con alte richieste`,`Supporto`,`Rientro allo sport più frequente dopo chirurgia (Eberbach 2017), ma studi di qualità bassa; Molina 2026 non trova una soglia di dislocazione validata. Decide l'ortopedico, insieme a ragazzo e famiglia`],[`Stretching del muscolo coinvolto nelle prime settimane`,`Evitare`,`Pratica clinica: mette in tensione il frammento staccato`],[`Sprint massimale e calcio prima che forza e dolore siano a posto`,`Evitare`,`Proposta operativa: sono i gesti che causano la lesione`]],
rts:{intro:`Non esistono criteri di rientro validati. Gli studi danno solo dati generali: ritorno allo sport quasi sempre (Molina 2026), in media dopo 11 settimane nelle avulsioni del piccolo trocantere (Volpi 2021), dopo circa 6 mesi nelle ischiatiche operate (Molina 2026); con il conservativo la forza è simmetrica a 3 mesi o più (Ratcliff 2025). Le soglie qui sotto sono proposte operative.`,c:[[`Dolore sulla sede`,`Palpazione dell'apofisi e contrazione resistita del muscolo coinvolto`,`Nessun dolore (proposta operativa)`,`Un dolore che resta può indicare un frammento non consolidato; il dolore persistente è più frequente nella SIAI e nella tuberosità ischiatica (Schuett 2015, Molina 2026).`],[`Via libera medica`,`Visita ortopedica ed eventuale RX, soprattutto nelle avulsioni ischiatiche o molto dislocate`,`Nessun segno di pseudoartrosi (proposta operativa)`,`Le pseudoartrosi sono rare, ma si concentrano nella tuberosità ischiatica e nelle dislocazioni oltre 20 mm (Schuett 2015).`],[`Forza`,`Dinamometro manuale in kg: flessione, estensione e abduzione d'anca, estensione e flessione del ginocchio`,`LSI ≥90% in tutte le misure (proposta operativa)`,`Ratcliff 2025 mostra che con il conservativo la simmetria si raggiunge: se manca, il ragazzo non è pronto.`],[`Forza in allungamento`,`Esercizio specifico della sede: Nordic o stacco rumeno (ischiatica), reverse Nordic (SIAI), flessione d'anca dall'estensione (SIAS, piccolo trocantere)`,`Senza dolore e simmetrica (proposta operativa)`,`Il muscolo strappa l'apofisi quando lavora allungato e veloce: va provato in quella condizione.`],[`Sprint`,`Sprint massimali su 20-40 m e partenze esplosive`,`Velocità vicina a quella prima dell'infortunio, senza dolore nemmeno il giorno dopo (proposta operativa)`,`Corsa e sprint sono il meccanismo più frequente (Schuett 2015, Ferraro 2023).`],[`Calcio`,`Calci corti, poi lunghi, poi in gioco e sotto fatica`,`Tutta la progressione senza dolore (proposta operativa)`,`Il calcio è il secondo meccanismo e causa metà delle avulsioni della SIAI (Schuett 2015).`],[`Gesti del rugby`,`Cambi di direzione, uscita dal ruck, placcaggio, mischia per gli avanti, allenamento pieno con la squadra`,`Allenamento completo senza sintomi (proposta operativa)`,`Il contatto aggiunge carichi improvvisi sull'anca che i test isolati non riproducono.`]],pre:[`Decisione condivisa con l'ortopedico, soprattutto se il frammento era molto dislocato o è stato operato`,`Primi sprint massimali e primi calci lunghi in allenamento, non in partita (proposta operativa)`,`Nel giovane contare il carico di tutte le squadre e di tutti gli sport praticati nella settimana (proposta operativa)`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`Non sono stati trovati studi sul rugby: i dati vengono soprattutto da calcio, football americano, baseball e ginnastica (Ferraro 2023, Rossi 2001).`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione delle avulsioni apofisarie (lacuna)`,`Alcuni ragazzi hanno dolore sull'apofisi nei giorni prima dell'avulsione (sintomi prodromici, Ferraro 2023): in un adolescente che sprinta e calcia va preso sul serio, riducendo sprint massimali e calci (proposta operativa)`,`Nei periodi di crescita rapida dosare sprint massimali e calci lunghi, aumentarli in modo graduale e curare la forza di anca e ginocchio (proposta operativa, senza studi specifici)`,`Programmi di riscaldamento come Activate riducono gli infortuni nel rugby scolastico (Hislop 2017), senza dati specifici sulle avulsioni`]}],
f:[[`Molina et al. 2026 – conservativo o chirurgia nelle avulsioni di bacino e anca dell'adolescente, revisione sistematica e metanalisi (J Pediatr Orthop)`,`Molina 2026 conservative versus surgical adolescent pelvic hip avulsion fractures meta-analysis`,`PMID 42084198`],[`Eberbach et al. 2017 – chirurgia o conservativo nelle avulsioni apofisarie del bacino: esiti e ritorno allo sport, revisione sistematica e metanalisi (BMC Musculoskelet Disord)`,`Eberbach operative versus conservative apophyseal avulsion fractures pelvis adolescents return to sports`,`PMID 28420360`],[`Schuett et al. 2015 – avulsioni apofisarie del bacino, revisione retrospettiva di 228 casi (J Pediatr Orthop)`,`Schuett pelvic apophyseal avulsion fractures retrospective review 228 cases`,`PMID 25321882`],[`Ferraro et al. 2023 – avulsioni apofisarie acute di bacino e anca negli adolescenti, sintesi di 719 casi (J Pediatr Orthop)`,`Ferraro acute pelvic hip apophyseal avulsion fractures adolescents 719 cases`,`PMID 36727766`],[`Rossi e Dragoni 2001 – avulsioni acute del bacino in atleti adolescenti: prevalenza, sede e sport in 203 casi (Skeletal Radiol)`,`Rossi Dragoni acute avulsion fractures pelvis adolescent competitive athletes 203 cases`,`PMID 11357449`],[`Ratcliff et al. 2025 – recupero della forza dopo trattamento conservativo delle avulsioni apofisarie del bacino (J Pediatr Orthop)`,`Ratcliff strength recovery nonsurgical treatment apophyseal avulsions pelvis`,`PMID 40454708`],[`Volpi et al. 2021 – trattamento conservativo delle avulsioni del piccolo trocantere in atleti adolescenti (Cureus)`,`Volpi conservative treatment avulsion injuries lesser trochanter adolescent athletes`,`PMID 34306849`],[`Hislop et al. 2017 – programma di controllo del movimento nel rugby scolastico, RCT a cluster (BJSM)`,`Hislop 2017 movement control exercise programme schoolboy rugby`,`PMID 28515056`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`]]});

S.push({id:`ileopsoas-groin-pain`,d:`Anca`,t:`Dolore inguinale correlato all'ileopsoas`,nw:1,
sub:`Approfondimento del groin pain: test HEC e flessione resistita da seduti, carico dei flessori d'anca, rientro a sprint e calcio`,
mat:[`Scheda nuova (ottobre 2026), costruita sulle fonti PubMed`],
key:[`È una delle entità del dolore inguinale secondo Doha (Weir 2015): classificazione generale, adduttori e programma Copenhagen sono nella scheda sul dolore inguinale nell'atleta; qui si approfondisce solo l'ileopsoas`,`È frequente: entità primaria nel 36% di 207 sportivi con dolore inguinale di lunga durata, e nel 33% le entità coesistono (Hölmich 2007)`,`Test migliori: il test HEC (sensibilità 94%, specificità 88%) e la flessione d'anca resistita da seduti; Thomas test, SLR in posizione neutra e snapping hip test sono risultati scarsi (Vandeputte 2025, popolazione non sportiva)`,`Il conservativo riesce nel 77-100% dei casi in popolazioni idiopatiche e sportive; nell'anca nativa il release artroscopico dell'ileopsoas non dà benefici chiari e lascia ipotrofia e perdita di forza (revisione sistematica, Vandeputte 2026)`,`Nel rugby professionistico le lesioni di flessori d'anca e quadricipite sono tra le più comuni dei trequarti in allenamento, e la corsa è il meccanismo prevalente (Brooks 2005); studi specifici sull'ileopsoas nel rugby non sono stati trovati`],
inq:[`Definizione di Doha: dolorabilità dell'ileopsoas alla palpazione, più probabile se c'è dolore alla flessione d'anca contro resistenza e/o all'allungamento dei flessori (Weir 2015; la stessa definizione è nella scheda sul dolore inguinale nell'atleta)`,`In 81 atleti con lesione inguinale acuta i test dei flessori d'anca hanno predetto male le lesioni viste alla RM (valore predittivo positivo 34-63%) e la loro localizzazione, mentre i test degli adduttori erano accurati; per i flessori d'anca la RM può aiutare a trovare la sede (Serner 2016)`,`Il quadro può essere acuto (lesione muscolo-tendinea dopo un calcio o uno sprint) o di lunga durata (tendinopatia, sovraccarico). Può riguardare l'anca nativa o comparire dopo una protesi d'anca, dove cause e risultati del trattamento sono diversi (Vandeputte 2026)`,`Nel dolore inguinale acuto di 110 atleti le lesioni di ileopsoas e retto femorale prossimale erano frequenti (15-25%), ma quando la diagnosi clinica era ileopsoas o retto femorale l'imaging trovava la lesione in un'altra sede nel 35-46% dei casi, contro il 3-6% degli adduttori (Serner 2015)`,`Meccanismi del dolore inguinale acuto: nel calcio soprattutto il gesto del calciare (40%), negli altri sport il cambio di direzione (31%) (Serner 2015). Nel rugby pesano sprint, calci e partenze esplosive (giudizio clinico)`,`La classificazione di Doha ha un accordo tra esaminatori moderato per l'ileopsoas (kappa 0,57); ordinare le entità per importanza clinica lo migliora, e quando c'era una sola entità l'accordo è stato completo (Heijboer 2022, 48 atleti)`,`Diagnosi differenziale: dolore correlato all'anca (FAI, labbro: vedi la scheda sul conflitto femoro-acetabolare), lesione prossimale del retto femorale, adduttori, dolore inguinale e pubico; nell'adolescente l'avulsione del piccolo trocantere (vedi la scheda sulle avulsioni apofisarie del bacino)`,`Nessun esame è un riferimento sicuro: negli studi diagnostici il riferimento è stato la riduzione del dolore dopo un'infiltrazione guidata dall'imaging (Vandeputte 2026)`],
tab:[{t:`L'ileopsoas nel dolore inguinale`,z:`I`,h:[`Dato`,`Fonte`],r:[[`Entità primaria nel 36% di 207 sportivi con dolore di lunga durata (adduttori 58%)`,`Hölmich 2007`],[`Più entità insieme nel 33% dei casi`,`Hölmich 2007`],[`Ileopsoas e retto femorale prossimale nel 15-25% delle lesioni inguinali acute`,`Serner 2015, 110 atleti`],[`Diagnosi clinica di ileopsoas o retto femorale localizzata altrove dall'imaging nel 35-46% dei casi`,`Serner 2015`],[`Accordo tra esaminatori per l'ileopsoas: kappa 0,57, moderato`,`Heijboer 2022`],[`Flessori d'anca e quadricipite tra le lesioni muscolari più comuni dei trequarti in allenamento`,`Brooks 2005, rugby professionistico`]]},{t:`Test clinici a confronto (Vandeputte 2025)`,z:`V`,h:[`Test`,`Risultato nello studio`],r:[[`Test HEC`,`Il migliore: sensibilità 94%, specificità 88%, AUC 0,99`],[`Flessione d'anca resistita da seduti`,`Buono, secondo in classifica`],[`SLR in extrarotazione`,`Terzo in classifica`],[`Extrarotazione d'anca resistita da seduti`,`Buono, quarto in classifica`],[`Thomas test, SLR in posizione neutra, snapping hip test`,`Scarsi`],[`Test provocativi da supini (revisione Vandeputte 2026)`,`Molto sensibili ma poco specifici`],[`Limite`,`44 pazienti, età media 48 anni, metà con protesi d'anca; riferimento: riduzione del dolore dopo infiltrazione guidata da fluoroscopia; rischio di bias alto; nessun dato sugli atleti`]]}],
red:[`Febbre, malessere, dolore che cresce anche a riposo, anca tenuta in flessione: escludere un ascesso dello psoas o un'artrite settica (pratica clinica).`,`Dolore inguinale da carico che peggiora con la corsa, dolore notturno: escludere una frattura da stress del collo del femore o del pube (pratica clinica, come nella scheda sul dolore inguinale nell'atleta).`,`Adolescente con dolore acuto dopo uno sprint o un calcio: escludere un'avulsione del piccolo trocantere (vedi la scheda sulle avulsioni apofisarie del bacino). Nell'adulto un'avulsione del piccolo trocantere va sempre inviata al medico (pratica clinica).`,`Sintomi addominali, urinari o testicolari, massa inguinale: invio al medico (pratica clinica).`,`Formicolii o debolezza sulla faccia anteriore della coscia: valutare il nervo femorale e la colonna lombare (pratica clinica).`],
yel:[`Dolore di lunga durata con poca fiducia nello sprint e nel calcio.`,`Convinzione che servano un esame o un intervento per guarire, mentre il percorso è quasi sempre conservativo.`,`Pressione per continuare a giocare a stagione in corso.`],
tst:[[`Palpazione dell'ileopsoas`,`Da supino con l'anca leggermente flessa: sotto il legamento inguinale, lateralmente all'arteria femorale; confronto con il lato sano.`,`Dolorabilità riconoscibile: è il criterio di base della definizione di Doha.`],[`Flessione d'anca resistita da seduti`,`Seduto sul bordo del lettino, solleva il ginocchio contro la resistenza della mano o del dinamometro.`,`Dolore inguinale riconoscibile. Tra i test buoni (Vandeputte 2025); la revisione consiglia di usarlo sempre insieme al test HEC.`],[`Test HEC (hip external rotation flexion ceiling)`,`Combina la flessione d'anca contro resistenza con l'extrarotazione, la funzione secondaria dell'ileopsoas. Per posizione e modalità di resistenza esatte fare riferimento all'articolo originale (Vandeputte 2025).`,`Sensibilità 94%, specificità 88% in una popolazione non sportiva, con rischio di bias alto: stime preliminari.`],[`Extrarotazione resistita da seduti e SLR in extrarotazione`,`Seduto: resistenza all'extrarotazione d'anca. Supino: sollevamento della gamba tesa con l'arto extraruotato.`,`Test buoni o utili nello stesso studio: completano il test HEC.`],[`Thomas test`,`Supino, un ginocchio al petto, l'altra gamba scende dal bordo del lettino.`,`Dà un'idea della lunghezza dei flessori, ma per la diagnosi è risultato scarso (Vandeputte 2025): non usarlo da solo.`],[`Esame delle altre entità e forza`,`Squeeze test e test dell'anca, come nella scheda sul dolore inguinale nell'atleta; forza della flessione d'anca da seduti con il dinamometro manuale, in kg.`,`Le entità coesistono spesso: classificarle e ordinarle per importanza migliora l'accordo (Heijboer 2022). La forza serve per il monitoraggio e il rientro.`]],
ex:[[`Isometrici dei flessori d'anca`,`i`,`5×30-45 s al 30-50% · RPE 3-5 · quotidiano (proposta operativa)`,`Seduto, spinta del ginocchio verso l'alto contro la mano o una cintura; poi da supino con anca e ginocchio a 90°.`,`Dolore oltre 3/10 o che resta il giorno dopo.`,`Intensità più alta, angoli diversi, extrarotazione aggiunta.`],[`Flessione d'anca con elastico o cavo`,`f`,`3×12-15 → 4×6-8 · RPE 6-8 · 2-3/sett. (proposta operativa)`,`Da seduto, sollevare il ginocchio oltre 90°; in piedi, ginocchio verso il petto con l'elastico alla caviglia; marcia da supino con l'elastico ai piedi.`,`Schiena che si inarca o bacino che ruota per compensare.`,`Carico più alto, poi esecuzione veloce.`],[`Flessori in allungamento`,`f`,`3×6-8 · RPE 6-8 · 2/sett. (proposta operativa)`,`Flessione d'anca al cavo partendo dall'anca estesa; split squat e affondi con l'anca posteriore in estensione; discesa lenta della gamba tesa da supino.`,`Iniziarli quando la flessione resistita è ancora dolorosa.`,`Range più ampio, velocità più alta.`],[`Controllo lombo-pelvico e antirotazione`,`c`,`3×8-10 o 3×20-30 s (proposta operativa)`,`Dead bug, Pallof press, plank laterale, ponte su una gamba.`,`Schiena che si inarca o bacino che ruota.`,`Dead bug con carico, esercizi in piedi e in corsa.`],[`Forza globale dell'anca`,`f`,`3×6-10 · RPE 7-8 · 2-3/sett. (proposta operativa)`,`Adduttori (Copenhagen: vedi la scheda sul dolore inguinale nell'atleta), hip thrust, squat, abduzione al cavo.`,`Trascurare gli adduttori: le entità spesso coesistono.`,`Carichi più alti, esercizi su una gamba.`],[`Corsa, andature e sprint`,`p`,`2-3 sedute/sett., velocità crescente (proposta operativa)`,`Skip, corsa al 60-70%, allunghi, sprint all'80-90% e poi massimali, partenze da fermo.`,`Partire dallo sprint massimale e dalle partenze esplosive.`,`Sprint con cambi di direzione e in situazioni di gioco.`],[`Calcio progressivo`,`p`,`2-3 sedute/sett. per chi calcia (proposta operativa)`,`Calci corti di precisione, poi medi, poi lunghi e piazzati, infine sotto fatica.`,`Molti calci lunghi nella stessa seduta appena rientrati.`,`Calci in gioco e sotto pressione.`]],
fasi:[{n:`Calma dei sintomi`,w:`circa 0-2 sett. (indicativo)`,o:`Ridurre il dolore e mantenere l'attività`,k:`Ridurre calci, sprint e tagli provocativi senza riposo totale; condizione fisica con attività non dolorose`,c:`Flessione resistita da seduti con dolore ≤2/10 (proposta operativa)`,e:[0,3]},{n:`Forza dei flessori`,w:`circa 2-6 sett. (indicativo)`,o:`Forza dei flessori d'anca e dell'anca nel suo insieme`,k:`Progressione da isometrico a dinamico, con controllo lombo-pelvico`,c:`Test HEC e flessione resistita senza dolore, LSI della flessione d'anca ≥80% (proposta operativa)`,e:[0,1,3,4]},{n:`Allungamento e velocità`,w:`circa 6-10 sett. (indicativo)`,o:`Forza dei flessori in allungamento, corsa veloce`,k:`Corsa lineare in progressione`,c:`LSI ≥90%, corsa all'80% senza dolore (proposta operativa)`,e:[1,2,4,5]},{n:`Campo`,w:`quando i criteri sono raggiunti; nessun tempo validato`,o:`Sprint massimale, calcio, cambi di direzione, contatto`,k:`Mantenere 1-2 sedute a settimana di forza di flessori e adduttori`,c:`Criteri del capitolo del rientro`,e:[2,4,5,6]}],
ev:[[`Trattamento conservativo con esercizio progressivo e gestione del carico`,`Centrale`,`Successo nel 77-100% in popolazioni idiopatiche e sportive (Vandeputte 2026), da studi osservazionali di qualità bassa o moderata: nessun RCT sugli atleti`],[`Esame clinico standardizzato: classificazione di Doha, test HEC e flessione resistita da seduti`,`Centrale`,`Accordo moderato tra esaminatori (Heijboer 2022); accuratezza dei test da studi ad alto rischio di bias in popolazioni non sportive (Vandeputte 2025, Vandeputte 2026)`],[`Infiltrazione guidata dall'imaging`,`Supporto`,`Miglioramento a breve termine nel 50-70% dei pazienti, efficacia a lungo termine limitata (Vandeputte 2026); utile anche come conferma diagnostica. Indicazione medica`],[`Release artroscopico dell'ileopsoas nell'anca nativa`,`Evitare`,`Quattro coorti comparative: nessun beneficio chiaro oltre il trattamento della patologia intra-articolare, con ipotrofia e perdita di forza in flessione (Vandeputte 2026)`],[`Diagnosi con il solo Thomas test o con la sola RM`,`Evitare`,`Thomas test scarso (Vandeputte 2025); discrepanza frequente tra clinica e imaging (Serner 2015)`]],
rts:{intro:`Non esistono criteri di rientro validati per il dolore correlato all'ileopsoas, né tempi medi di rientro negli atleti. I criteri qui sotto usano i test clinici migliori disponibili e i gesti del rugby che caricano i flessori d'anca; le soglie sono proposte operative.`,c:[[`Test provocativi`,`Test HEC e flessione d'anca resistita da seduti`,`Negativi, dolore 0-1/10 (proposta operativa)`,`Sono i test più accurati disponibili (Vandeputte 2025): se riproducono il dolore, l'ileopsoas non è pronto.`],[`Forza dei flessori d'anca`,`Dinamometro manuale in kg, da seduti a 90° di flessione, confronto tra lati`,`LSI ≥90% (proposta operativa)`,`Sprint e calcio chiedono una flessione d'anca potente; con il dinamometro si misura in modo semplice e ripetibile.`],[`Forza di adduttori e anca`,`Squeeze test con dinamometro e test della scheda sul dolore inguinale nell'atleta`,`LSI ≥90% e senza dolore (proposta operativa)`,`Le entità coesistono spesso (33% in Hölmich 2007): rientrare con gli adduttori deboli espone a una seconda entità.`],[`Sprint`,`Sprint massimali su 20-40 m e partenze esplosive da fermo`,`Velocità vicina a quella prima dell'infortunio, senza dolore nemmeno il giorno dopo (proposta operativa)`,`La corsa è il meccanismo prevalente degli infortuni in allenamento nel rugby professionistico (Brooks 2005).`],[`Calcio`,`Calci corti, lunghi e piazzati, poi sotto fatica`,`Volume abituale senza dolore (proposta operativa)`,`Calciare è il primo meccanismo del dolore inguinale acuto nel calcio (Serner 2015).`],[`Cambi di direzione e gesti del rugby`,`Tagli, uscita dal ruck, pick and go, mischia per gli avanti, allenamento pieno con la squadra`,`Allenamento completo senza sintomi (proposta operativa)`,`Il cambio di direzione è il primo meccanismo negli sport diversi dal calcio (Serner 2015).`],[`Risposta nelle 24 ore`,`Dolore la mattina dopo e ripetizione della flessione resistita`,`Nessun aumento rispetto al giorno prima (proposta operativa)`,`Il dolore di lunga durata tende a ripresentarsi quando il carico cresce troppo in fretta (giudizio clinico).`]],pre:[`Nel rugby professionistico le recidive degli infortuni in allenamento sono più gravi delle prime lesioni (35 contro 21 giorni persi, Brooks 2005): meglio una settimana in più che una ricaduta`,`Il precampionato concentra più infortuni del previsto (22% del tempo di allenamento, 34% degli infortuni, Brooks 2005): rientrare con un carico graduale (proposta operativa)`,`Primi sprint massimali e calci lunghi in allenamento, non in partita (proposta operativa)`,`Il ritorno allo sport è un continuum parallelo alla riabilitazione, non un esame finale (consenso di Berna, Ardern 2016)`],nota:`I test diagnostici sono stati studiati in popolazioni non sportive (età media 48 anni, metà con protesi d'anca); i dati sul rugby riguardano gli infortuni muscolari in generale, non l'ileopsoas.`},
sez:[{h:`Prevenzione`,b:[`Non sono stati trovati studi sulla prevenzione specifica del dolore correlato all'ileopsoas (lacuna)`,`Mantenere in stagione il rinforzo dei flessori d'anca e degli adduttori (per il Copenhagen vedi la scheda sul dolore inguinale nell'atleta) (proposta operativa)`,`Aumentare in modo graduale sprint e calci, soprattutto nel precampionato, quando nel rugby professionistico avviene una quota di infortuni più alta del tempo di allenamento (Brooks 2005)`,`Riconoscere presto il dolore inguinale: Hölmich 2007 ipotizza che un'entità ne preceda altre, ma è un'ipotesi non dimostrata`,`Misurare a inizio stagione la forza di flessione d'anca e lo squeeze test con il dinamometro, per avere un riferimento in caso di infortunio (proposta operativa)`]}],
f:[[`Serner et al. 2016 – l'esame clinico predice la presenza e la sede dei reperti alla RM nelle lesioni inguinali acute (BJSM)`,`Serner 2016 standardised clinical examination acute groin injuries MRI findings`,`PMID 27531521`],[`Weir et al. 2015 – accordo di Doha su terminologia e definizioni del dolore inguinale nell'atleta (BJSM)`,`Weir 2015 Doha agreement terminology definitions groin pain athletes`,`PMID 26031643`],[`Heijboer et al. 2022 – affidabilità tra esaminatori della classificazione di Doha in atleti maschi (Scand J Med Sci Sports)`,`Heijboer inter-examiner reliability Doha agreement classification groin pain male athletes`,`PMID 36259124`],[`Vandeputte et al. 2026 – diagnosi clinica e trattamento del dolore inguinale correlato all'ileopsoas, revisione sistematica (J Clin Med)`,`Clinical diagnosis and treatment of iliopsoas-related groin pain systematic review`,`PMID 42590015`],[`Vandeputte et al. 2025 – test clinici per la diagnosi di tendinopatia dell'ileopsoas (Clin Orthop Relat Res)`,`Vandeputte 2025 evaluation clinical tests diagnose iliopsoas tendinopathy`,`PMID 40388705`],[`Hölmich 2007 – il dolore inguinale di lunga durata negli sportivi in tre quadri clinici, studio prospettico su 207 pazienti (BJSM)`,`Holmich 2007 long-standing groin pain sportspeople three primary patterns clinical entity`,`PMID 17261557`],[`Serner et al. 2015 – diagnosi delle lesioni inguinali acute, studio prospettico su 110 atleti (Am J Sports Med)`,`Serner 2015 diagnosis acute groin injuries prospective study 110 athletes`,`PMID 25977522`],[`Brooks et al. 2005 – epidemiologia degli infortuni nel rugby professionistico inglese, parte 2: allenamento (BJSM)`,`Brooks 2005 epidemiology injuries English professional rugby union training injuries`,`PMID 16183775`],[`Ardern et al. 2016 – consenso di Berna sul ritorno allo sport (BJSM)`,`Ardern 2016 consensus statement return to sport Bern`,`PMID 27226389`]]});
